// 1. 基础类型与变量
// 字符串
let greeting = "Hello, World!";
let name = "Rust";

// 数值类型
let integer: i32 = 42;
let float: f64 = 3.14;
let boolean: bool = true;

// 2. 控制流
// if-else
if integer > 0 {
    println!("正数");
} else {
    println!("非正数");
}

// match 模式匹配
match integer {
    0 => println!("零"),
    1..=100 => println!("一到一百之间"),
    _ => println!("其他"),
}

// 3. 循环
// for 循环
for i in 0..5 {
    println!("循环: {}", i);
}

// while ...
let mut count = 0;
while count < 3 {
    println!("计数: {}", count);
    count += 1;
}

// ...
loop {
    if count >= 5 {
        break;
    }
    count += 1;
}

// 4. 函数
fn add(a: i32, b: i32) -> i32 {
    a + b
}

fn greet(name: &str) {
    println!("你好, {}!", name);
}

// 5. 所有权与借用
let s1 = String::from("hello");
let s2 = s1;  // s1 被移动到 s2

// 借用
let s3 = String::from("world");
let len = calculate_length(&s3);

fn calculate_length(s: &String) -> usize {
    s.len()
}

